file.content:
/* Reset, typography and page layout. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-ink);
  background: var(--color-bg);
}

h1,
h2,
h3,
p,
ul,
ol,
dl,
dd,
figure {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: var(--color-brand);
}

[hidden] {
  display: none !important;
}

h1 {
  font-size: 36px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.02em;
}

h2 {
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.01em;
}

h3 {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 700;
}

.container {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.section {
  padding: var(--space-7) 0 0;
}

.section-title {
  margin-bottom: var(--space-5);
}

.page-head {
  padding-top: var(--space-7);
}

.page-head .lede {
  max-width: 640px;
  margin-top: var(--space-3);
}

.lede {
  font-size: 18px;
  color: var(--color-muted);
}

.muted {
  color: var(--color-muted);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  border: 0;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

@media (max-width: 720px) {
  h1 {
    font-size: 28px;
  }

  h2 {
    font-size: 21px;
  }

  .container {
    padding: 0 var(--space-4);
  }

  .section,
  .page-head {
    padding-top: var(--space-6);
  }
}

content.content:
1	/* Shared components: header, button, card, form, table, modal, and friends. */
2	
3	/* Header */
4	
5	.site-header {
6	  position: sticky;
7	  top: 0;
8	  z-index: 100;
9	  background: var(--color-surface);
10	  border-bottom: 1px solid var(--color-line);
11	}
12	
13	.header-inner {
14	  display: flex;
15	  align-items: center;
16	  justify-content: space-between;
17	  height: var(--header-height);
18	}
19	
20	.brand {
21	  display: flex;
22	  align-items: center;
23	  gap: var(--space-2);
24	  font-size: 18px;
25	  font-weight: 800;
26	  color: var(--color-ink);
27	  text-decoration: none;
28	}
29	
30	.site-nav {
31	  display: flex;
32	  gap: var(--space-1);
33	}
34	
35	.nav-link {
36	  padding: var(--space-2) var(--space-3);
37	  border-radius: var(--radius-sm);
38	  font-size: 15px;
39	  font-weight: 600;
40	  color: var(--color-ink);
41	  text-decoration: none;
42	}
43	
44	.nav-link:hover {
45	  background: var(--color-bg);
46	}
47	
48	.nav-link[aria-current='page'] {
49	  color: var(--color-brand);
50	  background: var(--color-brand-tint);
51	}
52	
53	.nav-toggle {
54	  display: none;
55	  width: 40px;
56	  height: 40px;
57	  padding: 0;
58	  border: 1px solid var(--color-line);
59	  border-radius: var(--radius-sm);
60	  background: var(--color-surface);
61	  cursor: pointer;
62	}
63	
64	.nav-toggle-bar {
65	  display: block;
66	  width: 18px;
67	  height: 2px;
68	  margin: 4px auto;
69	  border-radius: 1px;
70	  background: var(--color-ink);
71	}
72	
73	/* Button */
74	
75	.btn {
76	  display: inline-flex;
77	  align-items: center;
78	  justify-content: center;
79	  padding: 10px 18px;
80	  border: 1px solid transparent;
81	  border-radius: var(--radius-md);
82	  font: inherit;
83	  font-size: 15px;
84	  font-weight: 700;
85	  line-height: 1.2;
86	  text-decoration: none;
87	  cursor: pointer;
88	}
89	
90	.btn-primary {
91	  background: var(--color-brand);
92	  color: #ffffff;
93	}
94	
95	.btn-primary:hover {
96	  background: var(--color-brand-dark);
97	}
98	
99	.btn-secondary {
100	  background: var(--color-surface);
101	  color: var(--color-ink);
102	  border-color: var(--color-line);
103	}
104	
105	.btn-secondary:hover {
106	  background: var(--color-bg);
107	}
108	
109	.btn-sm {
110	  padding: 6px 12px;
111	  border-radius: var(--radius-sm);
112	  font-size: 13px;
113	}
114	
115	.btn-lg {
116	  padding: 13px 24px;
117	  font-size: 16px;
118	}
119	
120	.btn[disabled] {
121	  opacity: 0.5;
122	  cursor: not-allowed;
123	}
124	
125	/* Card */
126	
127	.card {
128	  position: relative;
129	  background: var(--color-surface);
130	  border: 1px solid var(--color-line);
131	  border-radius: var(--radius-lg);
132	  box-shadow: var(--shadow-sm);
133	}
134	
135	.card-body {
136	  padding: var(--space-5);
137	}
138	
139	.card-thumb {
140	  height: 120px;
141	  border-radius: 13px 13px 0 0;
142	}
143	
144	.card h3 {
145	  margin-bottom: var(--space-2);
146	}
147	
148	.card p {
149	  font-size: 15px;
150	  color: var(--color-muted);
151	}
152	
153	.card-foot {
154	  display: flex;
155	  align-items: center;
156	  justify-content: space-between;
157	  margin-top: var(--space-4);
158	}
159	
160	.cards {
161	  display: grid;
162	  grid-template-columns: repeat(3, 1fr);
163	  gap: var(--space-5);
164	}
165	
166	.cards-4 {
167	  grid-template-columns: repeat(4, 1fr);
168	}
169	
170	.badge {
171	  position: absolute;
172	  top: -10px;
173	  right: -10px;
174	  padding: 3px 10px;
175	  border-radius: var(--radius-pill);
176	  background: var(--color-brand);
177	  color: #ffffff;
178	  font-size: 12px;
179	  font-weight: 700;
180	}
181	
182	.badge-sale {
183	  background: var(--color-danger);
184	}
185	
186	.price {
187	  font-size: 20px;
188	  font-weight: 800;
189	  color: var(--color-brand);
190	}
191	
192	/* Stat */
193	
194	.stats {
195	  display: grid;
196	  grid-template-columns: repeat(3, 1fr);
197	  gap: var(--space-4);
198	}
199	
200	.stat {
201	  padding: var(--space-4) var(--space-5);
202	  background: var(--color-surface);
203	  border: 1px solid var(--color-line);
204	  border-radius: var(--radius-lg);
205	  box-shadow: var(--shadow-md);
206	}
207	
208	.stat-value {
209	  font-size: 28px;
210	  font-weight: 800;
211	  line-height: 1.2;
212	  letter-spacing: -0.02em;
213	}
214	
215	.stat-label {
216	  font-size: 14px;
217	  color: var(--color-muted);
218	}
219	
220	/* Form */
221	
222	.form .btn {
223	  min-width: 140px;
224	}
225	
226	.form-field {
227	  margin-bottom: var(--space-4);
228	}
229	
230	.form-label {
231	  display: block;
232	  margin-bottom: var(--space-1);
233	  font-size: 14px;
234	  font-weight: 600;
235	}
236	
237	.form-input {
238	  display: block;
239	  width: 100%;
240	  padding: 10px 12px;
241	  border: 1px solid var(--color-line);
242	  border-radius: var(--radius-md);
243	  background: var(--color-surface);
244	  font: inherit;
245	  font-size: 15px;
246	  color: var(--color-ink);
247	}
248	
249	textarea.form-input {
250	  min-height: 120px;
251	  resize: vertical;
252	}
253	
254	.form-input:focus {
255	  outline: 2px solid var(--color-brand);
256	  outline-offset: 1px;
257	}
258	
259	.form-input.is-invalid {
260	  border-color: var(--color-danger);
261	}
262	
263	.form-error {
264	  margin-top: var(--space-1);
265	  font-size: 13px;
266	  color: var(--color-danger);
267	}
268	
269	.form-check {
270	  display: flex;
271	  align-items: flex-start;
272	  gap: var(--space-2);
273	  font-size: 14px;
274	}
275	
276	.form-check input {
277	  margin: 3px 0 0;
278	}
279	
280	.form-inline {
281	  display: flex;
282	  gap: var(--space-2);
283	}
284	
285	.form-inline .form-input {
286	  flex: 1;
287	  min-width: 0;
288	}
289	
290	/* Table */
291	
292	.table-wrap {
293	  overflow-x: auto;
294	  border: 1px solid var(--color-line);
295	  border-radius: var(--radius-lg);
296	  background: var(--color-surface);
297	}
298	
299	.table {
300	  width: 100%;
301	  border-collapse: collapse;
302	  font-size: 15px;
303	}
304	
305	.table th,
306	.table td {
307	  padding: var(--space-3) var(--space-4);
308	  border-bottom: 1px solid var(--color-line);
309	  text-align: left;
310	  white-space: nowrap;
311	}
312	
313	.table th {
314	  background: var(--color-bg);
315	  font-size: 13px;
316	  font-weight: 700;
317	  letter-spacing: 0.04em;
318	  text-transform: uppercase;
319	  color: var(--color-muted);
320	}
321	
322	.table tbody tr:last-child td {
323	  border-bottom: 0;
324	}
325	
326	.table .num {
327	  text-align: right;
328	}
329	
330	/* Pill */
331	
332	.pill {
333	  display: inline-block;
334	  padding: 2px 10px;
335	  border-radius: var(--radius-pill);
336	  font-size: 13px;
337	  font-weight: 600;
338	}
339	
340	.pill-ok {
341	  background: var(--color-success-tint);
342	  color: var(--color-success);
343	}
344	
345	.pill-warn {
346	  background: var(--color-warning-tint);
347	  color: var(--color-warning);
348	}
349	
350	.pill-err {
351	  background: var(--color-danger-tint);
352	  color: var(--color-danger);
353	}
354	
355	/* Alert */
356	
357	.alert {
358	  padding: var(--space-3) var(--space-4);
359	  border: 1px solid transparent;
360	  border-radius: var(--radius-md);
361	  font-size: 15px;
362	}
363	
364	.alert-ok {
365	  background: var(--color-success-tint);
366	  border-color: #b7e2c6;
367	  color: var(--color-success);
368	}
369	
370	/* Modal */
371	
372	.modal-overlay {
373	  position: fixed;
374	  inset: 0;
375	  z-index: 200;
376	  display: flex;
377	  align-items: center;
378	  justify-content: center;
379	  padding: var(--space-4);
380	  background: rgba(31, 35, 40, 0.5);
381	}
382	
383	.modal-dialog {
384	  width: 100%;
385	  max-width: 480px;
386	  background: var(--color-surface);
387	  border-radius: var(--radius-lg);
388	  box-shadow: var(--shadow-md);
389	}
390	
391	.modal-header {
392	  display: flex;
393	  align-items: center;
394	  justify-content: space-between;
395	  padding: var(--space-4) var(--space-5);
396	  border-bottom: 1px solid var(--color-line);
397	}
398	
399	.modal-close {
400	  width: 32px;
401	  height: 32px;
402	  padding: 0;
403	  border: 0;
404	  border-radius: var(--radius-sm);
405	  background: transparent;
406	  font: inherit;
407	  font-size: 22px;
408	  line-height: 1;
409	  color: var(--color-muted);
410	  cursor: pointer;
411	}
412	
413	.modal-body {
414	  padding: var(--space-5);
415	}
416	
417	.modal-footer {
418	  display: flex;
419	  justify-content: flex-end;
420	  gap: var(--space-2);
421	  padding: var(--space-4) var(--space-5);
422	  border-top: 1px solid var(--color-line);
423	}
424	
425	.detail-list {
426	  display: grid;
427	  grid-template-columns: 120px 1fr;
428	  gap: var(--space-2) var(--space-4);
429	}
430	
431	.detail-list dt {
432	  font-size: 14px;
433	  color: var(--color-muted);
434	}
435	
436	.detail-list dd {
437	  font-weight: 600;
438	}
439	
440	/* Footer */
441	
442	.site-footer {
443	  margin-top: var(--space-8);
444	  padding: var(--space-5) 0;
445	  border-top: 1px solid var(--color-line);
446	  font-size: 14px;
447	  color: var(--color-muted);
448	}
449	
450	.footer-inner {
451	  display: flex;
452	  align-items: center;
453	  justify-content: space-between;
454	  gap: var(--space-4);
455	}
456	
457	.footer-links {
458	  display: flex;
459	  gap: var(--space-4);
460	}
461	
462	.footer-links a {
463	  color: var(--color-muted);
464	}
465	
466	@media (max-width: 720px) {
467	  .nav-toggle {
468	    display: block;
469	  }
470	
471	  .site-nav {
472	    display: none;
473	    position: absolute;
474	    top: var(--header-height);
475	    right: 0;
476	    left: 0;
477	    flex-direction: column;
478	    gap: 0;
479	    padding: var(--space-2) var(--space-4) var(--space-4);
480	    background: var(--color-surface);
481	    border-bottom: 1px solid var(--color-line);
482	    box-shadow: var(--shadow-md);
483	  }
484	
485	  .site-nav.is-open {
486	    display: flex;
487	  }
488	
489	  .nav-link {
490	    padding: var(--space-3);
491	  }
492	
493	  .cards,
494	  .cards-4,
495	  .stats {
496	    grid-template-columns: 1fr;
497	  }
498	
499	  .footer-inner {
500	    flex-direction: column;
501	    align-items: flex-start;
502	  }
503	}
