PORT=4173 node -e '
const { chromium } = require("playwright");
const { spawn } = require("child_process");
const srv = spawn("node", ["server.js"], { env: { ...process.env, PORT: "4173" }, stdio: "ignore" });
(async () => {
  await new Promise(r => setTimeout(r, 800));
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const failed = [];
  page.on("requestfailed", r => failed.push(r.url() + " :: " + (r.failure() && r.failure().errorText)));
  page.on("response", r => { if (r.status() >= 400) failed.push(r.status() + " " + r.url()); });
  await page.goto("http://127.0.0.1:4173/", { waitUntil: "networkidle" });
  const info = await page.evaluate(async () => {
    await document.fonts.ready;
    const h1 = document.querySelector("h1");
    return {
      fontsStatus: document.fonts.status,
      loadedFamilies: [...document.fonts].map(f => f.family + ":" + f.status),
      h1Font: getComputedStyle(h1).fontFamily,
      usedFont: (() => { const c = document.createElement("canvas").getContext("2d"); c.font = "16px \"Acme Sans\""; return c.measureText("abcdef").width; })()
    };
  });
  console.log("FAILED REQUESTS:", JSON.stringify(failed, null, 2));
  console.log("FONT INFO:", JSON.stringify(info, null, 2));
  await browser.close();
  srv.kill();
})().catch(e => { console.error(e); srv.kill(); process.exit(1); });
' 2>&1 | tail -30

